mapper.select:
SELECT id, insurance_type_id, policy_number, insured, expiry_date
FROM insurances
WHERE id = #{id}

mapper.update:
UPDATE insurances
SET insurance_type_id = #{insuranceTypeId},
    policy_number = #{policyNumber},
    insured = #{insured},
    expiry_date = #{expiryDate}
WHERE id = #{id}
